    def __init__(self):
        self._dependents = []

    def _add_dependent(self, dependent):
        self._dependents.append(dependent)

    def _notify(self):
        """Recompute all affected compute cells in topological order and fire callbacks."""
        affected = []
        seen = set()
        stack = [self]
        while stack:
            cell = stack.pop()
            for dep in cell._dependents:
                if id(dep) not in seen:
                    seen.add(id(dep))
                    affected.append(dep)
                    stack.append(dep)
        if not affected:
            return
        affected_ids = set(seen)
        pending = {}
        for cell in affected:
            pending[id(cell)] = sum(1 for inp in cell._inputs if id(inp) in affected_ids)
        updated = set()
        ready = [cell for cell in affected if pending[id(cell)] == 0]
        while ready:
            cell = ready.pop()
            if id(cell) in updated:
                continue
            updated.add(id(cell))
            cell._recompute()
            for dep in cell._dependents:
                if id(dep) in affected_ids:
                    pending[id(dep)] -= 1
                    if pending[id(dep)] == 0:
                        ready.append(dep)
```

Wait, there's a subtle issue with `updated` and the ready queue: a cell could be added to `ready` multiple times (each time one of its inputs finishes). The `updated` check handles that.

But another subtle point: `pending` only counts affected inputs. If a cell has 2 affected inputs, both must finish. Each time a dependent input is recomputed, we decrement. Good.

